 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The key is a small rectangle whose rows repeat the same color sequence.
    # Find repeated nonzero row-patterns; among them use the one with >1 colors.
    key = None
    for r0 in range(h):
        for r1 in range(r0 + 2, h + 1):
            rows = grid[r0:r1]
            for c0 in range(w):
                for c1 in range(c0 + 2, w + 1):
                    seq = rows[0][c0:c1]
                    if len(set(seq)) < 2 or 0 in seq:
                        continue
                    if all(row[c0:c1] == seq for row in rows):
                        # Require the rectangle to be exactly the nonzero key cells.
                        if all(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1)):
                            key = (r0, r1, c0, c1, seq[:])
                            break
                if key:
                    break
            if key:
                break
        if key:
            break
    if key is None:
        return out

    kr0, kr1, kc0, kc1, colors = key
    key_cells = {(r, c) for r in range(kr0, kr1) for c in range(kc0, kc1)}

    # Find the largest 4-connected component of color 1 outside the key: this
    # is the shape to be repeated. (The key itself can contain color 1.)
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in key_cells or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                            and (nr, nc) not in key_cells and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)
    if not components:
        return out
    shape = max(components, key=len)
    minr = min(r for r, c in shape)
    maxr = max(r for r, c in shape)
    minc = min(c for r, c in shape)
    maxc = max(c for r, c in shape)
    sh, sw = maxr - minr + 1, maxc - minc + 1
    pattern = {(r - minr, c - minc) for r, c in shape}
    idx = colors.index(1)
    top0 = minr - idx * sh

    # Remove the color key and existing colored copies; redraw the complete
    # ordered stack of the template, anchored at the original 1-colored copy.
    for r, c in key_cells:
        out[r][c] = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in key_cells:
                # Clear repeated-object area while leaving unrelated content intact.
                if minr - len(colors) * sh <= r <= maxr + len(colors) * sh:
                    out[r][c] = 0
    for i, color in enumerate(colors):
        top = top0 + i * sh
        for dr, dc in pattern:
            rr, cc = top + dr, minc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
